I have a working Roman numeral converter and I'm adding more test coverage. The existing tests pass, but I'm getting failures with the new ones I added. Can you fix the implementation to make all tests pass?

```python
def to_roman(n: int) -> str:
    """
    Convert a positive integer to its Roman numeral representation.

    Args:
        n: A positive integer between 1 and 3999
    Returns:
        Roman numeral string using standard subtractive notation
    """
    val = [
        1000, 900, 500, 400,
        100, 90, 50, 40,
        10, 9, 5, 4,
        1
    ]
    syms = [
        'M', 'CM', 'D', 'CD',
        'C', 'XC', 'L', 'XL',
        'X', 'IX', 'V', 'IV',
        'I'
    ]
    result = ''
    for i in range(len(val)):
        while n >= val[i]:
            result += syms[i]
            n -= val[i]
    return result


# Existing passing tests
def test_one():
    assert to_roman(1) == 'I'

def test_four():
    assert to_roman(4) == 'IV'

def test_nine():
    assert to_roman(9) == 'IX'

def test_fourteen():
    assert to_roman(14) == 'XIV'

def test_forty():
    assert to_roman(40) == 'XL'

def test_ninety():
    assert to_roman(90) == 'XC'

def test_four_hundred():
    assert to_roman(400) == 'CD'

def test_nine_hundred():
    assert to_roman(900) == 'CM'

def test_1994():
    assert to_roman(1994) == 'MCMXCIV'

def test_3999():
    assert to_roman(3999) == 'MMMCMXCIX'

# New tests being added for additional coverage
def test_forty_nine():
    assert to_roman(49) == 'XLIX'

def test_forty_four():
    # Forty-four should use additive notation for L
    assert to_roman(44) == 'XLIV'

def test_ninety_nine():
    assert to_roman(99) == 'XCIX'

def test_three_thousand_six_hundred():
    assert to_roman(3600) == 'MMMDCCC'

def test_nineteen_ninety_nine():
    # Standard subtractive: 1999 = M + CM + XC + IX
    assert to_roman(1999) == 'MCMXCIX'

def test_two_thousand_twenty_one():
    assert to_roman(2021) == 'MMXXI'

def test_three_thousand_six_hundred_additive():
    # 3600 = MMM + DC + C, so MMMDCCC... wait, actually DC=600, so MMM+DC = 3600, which is MMMDCIC
    assert to_roman(3600) == 'MMMDCIC'
```

