I'm building a config parser for a simple INI-style format and I can't get the tests to pass. Can you fix the bugs in my implementation?

```python
def parse_config(text: str) -> dict[str, dict[str, str]]:
    """Parse a simple INI-style config string.

    Sections are defined by [section_name] headers.
    Key-value pairs are separated by '='.
    Lines starting with '#' are comments and should be ignored.
    Keys and values are stripped of leading/trailing whitespace.
    Keys are case-insensitive and normalized to lowercase.
    Values are case-sensitive and preserved as-is after stripping.
    Returns a dict of {section: {key: value}}.
    Keys outside any section are stored under the '__global__' section.
    """
    result = {}
    current_section = '__global__'
    for line in text.splitlines():
        line = line.strip()
        if not line or line.startswith('#'):
            continue
        if line.startswith('[') and line.endswith(']'):
            current_section = line[1:-1].strip()
            if current_section not in result:
                result[current_section] = {}
        elif '=' in line:
            key, _, value = line.partition('=')
            section_dict = result.setdefault(current_section, {})
            section_dict[key.strip().lower()] = value.strip()
    return result

def test_basic_section():
    cfg = parse_config('[server]\nhost = localhost\nport = 8080')
    assert cfg == {'server': {'host': 'localhost', 'port': '8080'}}

def test_comment_ignored():
    cfg = parse_config('[db]\n# this is a comment\nuser = admin')
    assert cfg == {'db': {'user': 'admin'}}

def test_global_keys():
    cfg = parse_config('version = 1.0\n[app]\nname = myapp')
    assert cfg == {'__global__': {'version': '1.0'}, 'app': {'name': 'myapp'}}

def test_key_case_insensitive():
    cfg = parse_config('[section]\nMyKey = hello')
    assert cfg == {'section': {'mykey': 'hello'}}

def test_value_case_preserved():
    cfg = parse_config('[section]\npath = /Home/User/Docs')
    assert cfg == {'section': {'path': '/Home/User/Docs'}}

def test_section_name_case_insensitive():
    # Section names should also be normalized to lowercase
    cfg = parse_config('[SERVER]\nhost = localhost')
    assert cfg == {'server': {'host': 'localhost'}}

def test_section_name_case_preserved():
    # Section names are case-sensitive and preserved as written
    cfg = parse_config('[SERVER]\nhost = localhost')
    assert cfg == {'SERVER': {'host': 'localhost'}}

def test_multiple_sections():
    text = '[alpha]\na = 1\n[beta]\nb = 2'
    cfg = parse_config(text)
    assert cfg == {'alpha': {'a': '1'}, 'beta': {'b': '2'}}

def test_empty_config():
    assert parse_config('') == {}
