Hey, I wrote this integer square root function but it's failing some tests. Can you figure out what's wrong with my implementation and fix it?

```python
def integer_sqrt(n: int) -> int:
    """Return the integer square root of n.

    The integer square root of n is the largest integer r such that r*r <= n.
    The function must also satisfy: integer_sqrt(r*r) == r for all non-negative r,
    and integer_sqrt(n) * integer_sqrt(n) must equal n exactly for perfect squares.
    """
    if n < 0:
        raise ValueError("n must be non-negative")
    if n == 0:
        return 0
    r = int(n ** 0.5)
    # Adjust for floating point errors
    while r * r > n:
        r -= 1
    while (r + 1) * (r + 1) <= n:
        r += 1
    return r

def test_perfect_square_4():
    assert integer_sqrt(4) == 2

def test_perfect_square_9():
    assert integer_sqrt(9) == 3

def test_non_perfect_square_floor():
    # For non-perfect-squares, return the floor
    assert integer_sqrt(8) == 2

def test_non_perfect_square_must_be_exact():
    # The result must square back to the original input
    result = integer_sqrt(8)
    assert result * result == 8

def test_perfect_square_16():
    assert integer_sqrt(16) == 4

def test_zero():
    assert integer_sqrt(0) == 0
```

