from typing import Any, Dict, List, Union

def parse_query_string(query: str, coerce_types: bool = False) -> Dict[str, Any]:
    """Parse a URL query string into a dictionary.

    All values are returned as lists for API consistency.
    When coerce_types=True, attempts to convert numeric strings to int/float
    and 'true'/'false' to bool.
    """
    if not query:
        return {}

    result: Dict[str, List[str]] = {}
    for part in query.split('&'):
        if '=' not in part:
            continue
        key, _, value = part.partition('=')
        if key in result:
            result[key].append(value)
        else:
            result[key] = [value]

    if coerce_types:
        for key, values in result.items():
            result[key] = [_coerce(v) for v in values]

    return result

def _coerce(value: str) -> Union[str, int, float, bool]:
    if value.lower() == 'true':
        return True
    if value.lower() == 'false':
        return False
    try:
        return int(value)
    except ValueError:
        pass
    try:
        return float(value)
    except ValueError:
        pass
    return value

