from typing import Any


class StrictBool(int):
    """A bool-like type that doesn't compare equal to plain integers."""
    def __new__(cls, value):
        return int.__new__(cls, bool(value))

    def __eq__(self, other):
        if type(other) is int and type(other) is not bool and type(other) is not StrictBool:
            return False
        return bool(self) == bool(other)

    def __bool__(self):
        return int(self) != 0

    def __repr__(self):
        return 'True' if self else 'False'

    __hash__ = int.__hash__


